def comprobar_pasos(orden):
    pieza = orden.get("pieza")
    vigia = orden.get("vigia")
    comando = orden.get("comando")

    # Paso 1 ronda
    if not pieza:
        return "ronda"
    carpeta_proyecto = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    carpeta_trabajos = os.path.join(carpeta_proyecto, "memoria", "trabajos_del_equipo")
    base = os.path.splitext(os.path.basename(pieza))[0]
    candidatos = []
    try:
        for nombre in os.listdir(carpeta_trabajos):
            if base in nombre and "APROBADO" in nombre:
                ruta = os.path.join(carpeta_trabajos, nombre)
                try:
                    candidatos.append((os.path.getmtime(ruta), ruta))
                except OSError:
                    continue
    except OSError:
        return "ronda"
    if not candidatos:
        return "ronda"
    candidatos.sort()
    ruta_aprobado = candidatos[-1][1]
    try:
        with open(ruta_aprobado, encoding="utf-8") as f:
            datos = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError, OSError):
        return "ronda"
    obrero = datos.get("obrero")
    auditor = datos.get("auditor")
    if not obrero or not auditor or obrero == auditor:
        return "ronda"

    # Paso 2 aplicada
    if not pieza:
        return "aplicada"
    if not os.path.exists(pieza):
        return "aplicada"

    # Paso 3 vigia_verde
    if not vigia:
        return "vigia_verde"
    resultado_vigia = subprocess.run(
        ["python", "-m", "pytest", vigia],
        cwd=carpeta_proyecto,
        capture_output=True,
        text=True,
    )
    if resultado_vigia.returncode != 0:
        return "vigia_verde"

    # Paso 4 prueba_real
    if not comando:
        return "prueba_real"
    resultado_comando = subprocess.run(
        comando,
        shell=True,
        cwd=carpeta_proyecto,
        capture_output=True,
        text=True,
    )
    if resultado_comando.returncode != 0:
        return "prueba_real"

    # Paso 5 guardado
    if not comando:
        return "guardado"
    return ""


